#!/usr/bin/env python3
"""CLI wrapper generated by api-tool-builder. Same tools, same safety rules as the MCP server.

  python cli.py list
  python cli.py describe create_message
  python cli.py call create_message --args '{"to":"<recipient>","body":"<text>"}'
  python cli.py call create_message --args-file args.json
Exit code 0 = ok, 1 = tool error, 2 = usage error. Output is always JSON on stdout.
"""
import argparse
import json
import sys
from pathlib import Path

from core import ApiTools


def main():
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    sub = ap.add_subparsers(dest="cmd", required=True)
    sub.add_parser("list")
    d = sub.add_parser("describe"); d.add_argument("name")
    c = sub.add_parser("call"); c.add_argument("name")
    c.add_argument("--args", default="{}"); c.add_argument("--args-file")
    a = ap.parse_args()
    t = ApiTools(Path(__file__).parent)
    entries = {e["name"]: e for e in t.list_tools()}
    if a.cmd == "list":
        print(json.dumps([{"name": n, "safety": e["safety"], "description": e["description"]} for n, e in entries.items()], indent=2))
    elif a.cmd == "describe":
        if a.name not in entries:
            print(json.dumps({"ok": False, "error": f"unknown tool {a.name}", "available": sorted(entries)})); sys.exit(2)
        print(json.dumps(entries[a.name], indent=2))
    else:
        raw = Path(a.args_file).read_text() if a.args_file else a.args
        try:
            args = json.loads(raw)
        except json.JSONDecodeError as e:
            print(json.dumps({"ok": False, "error": f"--args is not valid JSON: {e}"})); sys.exit(2)
        res = t.call_tool(a.name, args)
        print(json.dumps(res, indent=2, default=str))
        sys.exit(0 if res.get("ok") else 1)


if __name__ == "__main__":
    main()
